// Focused regression test for the embedded-PRO layout root cause.
//
// The official @pascal-app/editor@0.9.2 package ships ZERO css (it is
// source-only JS); all of its Tailwind utility classes (flex-1, bg-neutral-100,
// object-cover, ...) and theme variables are generated by the *consuming app's*
// Tailwind pipeline scanning packages/editor/src. Our pro.css carries an
// `@source` directive that must point at the real (symlinked) source dirs so
// Tailwind actually scans them — otherwise Editor utilities are never generated
// and the viewport collapses to a narrow strip / assets render un-sized.
//
// This test fails if those @source globs stop resolving to real directories
// (the exact regression that broke the layout).
import fs from 'node:fs';
import path from 'node:path';
import { describe, it, expect } from 'vitest';

const PRO_CSS = path.resolve(__dirname, './pro.css');

describe('pro.css @source targets the real Editor/Nodes source', () => {
  const css = fs.readFileSync(PRO_CSS, 'utf8');
  const sources = [...css.matchAll(/@source\s+"([^"]+)"/g)].map((m) => m[1]);

  it('declares @source for editor and nodes', () => {
    expect(sources.some((s) => s.includes('@pascal-app/editor/src'))).toBe(true);
    expect(sources.some((s) => s.includes('@pascal-app/nodes/'))).toBe(true);
  });

  it('every @source path resolves to a directory that actually contains .tsx', () => {
    // pro.css lives in src/features/pro/; the @source paths are relative to it.
    for (const s of sources) {
      const abs = path.resolve(__dirname, s);
      expect(fs.existsSync(abs), `@source "${s}" does not resolve`).toBe(true);
      const hasTsx = fs.readdirSync(abs).some(
        (f) =>
          f.endsWith('.tsx') ||
          f.endsWith('.ts') ||
          f.endsWith('.js') ||
          f.endsWith('.jsx') ||
          (fs.statSync(path.join(abs, f)).isDirectory()),
      );
      expect(hasTsx, `@source "${s}" resolves to an empty/unexpected dir`).toBe(true);
    }
  });

  it('does NOT rely on the broken src/node_modules/.pnpm glob', () => {
    expect(css).not.toMatch(/@source\s+"\.\.\/\.\.\/node_modules\/\.pnpm/);
  });
});
